-- QA test data for one user. Generated by gen_testdata.py - safe to re-run.
--
--   mysqlsh --sql --host=localhost --user=<user> --schema=jobtrail --file docs/sql/20-test-data.sql
--   (set @email below first)
--
-- Only rows created by this script are replaced: they carry created_at with a .777 millisecond fraction.
-- The user's own data and account (password, settings) are never touched. All times are UTC and relative to NOW,
-- so re-run it whenever the 'upcoming' interviews have become past.
SET NAMES utf8mb4;
SET time_zone = '+00:00';
SET @email := 'akram@gmail.com';
SET @uid := (SELECT id FROM users WHERE email = @email);
SELECT IF(@uid IS NULL, 'USER NOT FOUND - register it in the app first', CONCAT('Seeding user ', @uid)) AS info;

DELETE FROM notifications WHERE user_id = @uid AND MICROSECOND(created_at) = 777000;
DELETE FROM job_applications WHERE user_id = @uid AND MICROSECOND(created_at) = 777000;

